"""Unit tests for exact text and JSON rendering."""

import json

from wordstat.output import render_json, render_text


def test_render_text_emits_exact_four_lf_terminated_lines():
    result = {
        "lines": 3,
        "words": 8,
        "chars": 33,
        "top": [
            {"word": "cat", "count": 2},
            {"word": "the", "count": 2},
            {"word": "a", "count": 1},
        ],
    }

    assert render_text(result) == (
        "lines: 3\n"
        "words: 8\n"
        "chars: 33\n"
        "top: cat=2 the=2 a=1\n"
    )


def test_render_text_preserves_unicode_without_changing_line_ending():
    result = {
        "lines": 1,
        "words": 2,
        "chars": 4,
        "top": [
            {"word": "\u00e9t\u00e9", "count": 1},
            {"word": "\u03c9", "count": 1},
        ],
    }

    assert render_text(result) == "lines: 1\nwords: 2\nchars: 4\ntop: \u00e9t\u00e9=1 \u03c9=1\n"


def test_render_text_uses_bare_top_line_when_no_words():
    result = {"lines": 0, "words": 0, "chars": 0, "top": []}

    rendered = render_text(result)

    assert rendered == "lines: 0\nwords: 0\nchars: 0\ntop:\n"
    assert rendered.endswith("top:\n")
    assert not rendered.endswith("top: \n")


def test_render_json_uses_default_separators_and_required_key_order():
    result = {
        "lines": 3,
        "words": 8,
        "chars": 33,
        "top": [
            {"word": "cat", "count": 2},
            {"word": "the", "count": 2},
        ],
    }

    assert render_json(result) == (
        '{"lines": 3, "words": 8, "chars": 33, "top": '
        '[{"word": "cat", "count": 2}, {"word": "the", "count": 2}]}\n'
    )


def test_render_json_preserves_insertion_order_of_top_entry_keys():
    result = {
        "top": [{"count": 7, "word": "z"}],
        "chars": 1,
        "words": 1,
        "lines": 1,
    }

    rendered = render_json(result)

    assert rendered == '{"top": [{"count": 7, "word": "z"}], "chars": 1, "words": 1, "lines": 1}\n'
    assert list(json.loads(rendered)) == ["top", "chars", "words", "lines"]


def test_render_json_emits_one_lf_terminated_line_for_no_words():
    result = {"lines": 0, "words": 0, "chars": 0, "top": []}

    rendered = render_json(result)

    assert rendered == '{"lines": 0, "words": 0, "chars": 0, "top": []}\n'
    assert rendered.count("\n") == 1
    assert not rendered.endswith("\n\n")

"""Unit tests for counting and ranking decoded text."""

import pytest

from wordstat.analyzer import analyze, count_text, count_words, rank_words


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("", {"lines": 0, "words": 0, "chars": 0}),
        ("one", {"lines": 1, "words": 1, "chars": 3}),
        ("one\n", {"lines": 2, "words": 1, "chars": 4}),
        ("one\n\n", {"lines": 3, "words": 1, "chars": 5}),
        ("one\r\ntwo", {"lines": 2, "words": 2, "chars": 8}),
        ("one\rtwo", {"lines": 2, "words": 2, "chars": 7}),
        ("one\vtwo\nthree\x85four", {"lines": 3, "words": 4, "chars": 19}),
        ("\ufeff", {"lines": 1, "words": 0, "chars": 1}),
        ("a\ufeffb", {"lines": 1, "words": 2, "chars": 3}),
    ],
)
def test_count_text_uses_contract_formulas(text, expected):
    assert count_text(text) == expected


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("", []),
        ("The cat 42 CAT!", ["the", "cat", "42", "cat"]),
        ("\u00c0\u00c9\u03b1\u03a9 42 aBc-x_z", ["42", "abc", "x", "z"]),
        ("caf\u00e9 r\u00e9sum\u00e9 Ünicode", ["caf", "r", "sum", "nicode"]),
        ("a\ufeffb", ["a", "b"]),
    ],
)
def test_count_words_lowercases_then_matches_ascii_alphanumeric_tokens(
    text, expected
):
    assert count_words(text) == expected


def test_rank_words_orders_by_count_then_ascending_word():
    text = "z z a a m m b"

    assert rank_words(text, top=4) == [
        {"word": "a", "count": 2},
        {"word": "m", "count": 2},
        {"word": "b", "count": 1},
        {"word": "z", "count": 1},
    ]


def test_rank_words_defaults_to_three_entries():
    text = "a a b b c c d e"

    assert rank_words(text) == [
        {"word": "a", "count": 2},
        {"word": "b", "count": 2},
        {"word": "c", "count": 2},
    ]


def test_rank_words_truncates_to_requested_limit():
    text = "dog dog cat bird bird"

    assert rank_words(text, top=2) == [
        {"word": "bird", "count": 2},
        {"word": "dog", "count": 2},
    ]


def test_rank_words_returns_all_entries_when_fewer_than_limit():
    assert rank_words("alpha beta beta", top=10) == [
        {"word": "beta", "count": 2},
        {"word": "alpha", "count": 1},
    ]


def test_rank_words_returns_empty_list_for_no_words():
    assert rank_words("\n \t\ufeff") == []


def test_analyze_combines_counts_and_ranking():
    text = "The cat sat.\nThe cat ran!\nA dog."

    assert analyze(text, top=3) == {
        "lines": 3,
        "words": 8,
        "chars": 33,
        "top": [
            {"word": "cat", "count": 2},
            {"word": "the", "count": 2},
            {"word": "a", "count": 1},
        ],
    }


def test_analyze_handles_empty_and_no_word_input():
    assert analyze("") == {"lines": 0, "words": 0, "chars": 0, "top": []}
    assert analyze("\n \ufeff") == {"lines": 2, "words": 0, "chars": 4, "top": []}
